M(3,'«إجراء مقابلات عميقة، ومفتوحة (Open-ended)» هو:',['التفاعل (Engage)','الملاحظة (Observe)','الانغماس (Immerse)','التعريف (Define)']);
T(3,'الانغماس (Immerse) هو تجربة ما يمر به المستخدم بنفسك.');
F(3,'تقوم مرحلة التعاطف على رؤية العالم من زاوية المصمم.','تقوم مرحلة التعاطف على رؤية العالم من زاوية المستخدم.');
T(3,'من صور التعاطف السماع إلى القصص الشخصية للجمهور المستهدف، ومواقفهم التي يمرون بها.');
M(3,'الهدف من مرحلة التعريف:',['تحديد «المشكلة الحقيقية»، وصياغتها في جملة واحدة واضحة','توليد أكبر عدد من الأفكار','بناء نموذج أولي','اختبار الحل على المستخدمين']);
F(3,'الدافع في مرحلة التعريف هو حل أعراض المشكلة لا أصلها.','الدافع في مرحلة التعريف هو حل أصل المشكلة، وليست الأعراض.');
M(3,'«سر» مرحلة التعريف هو استخدام صيغة:',['«كيف يمكننا أن...؟» (How Might We – HMW)','«لماذا؟» خمس مرات','«نعم، و...»','«ماذا لو عكسنا الفكرة؟»']);
M(3,'في صيغة HMW، كلمة «كيف» (How):',['تفترض أن هناك حلاً ممكناً','تمنحنا الحرية لاقتراح أفكار قد تنجح وقد تفشل','تؤكد على العمل الجماعي التعاوني','تحدد الميزانية المطلوبة']);
M(3,'في صيغة HMW، كلمة «يمكننا» (Might):',['تمنحنا الحرية لاقتراح أفكار قد تنجح، وقد تفشل','تفترض أن هناك حلاً ممكناً','تؤكد على العمل الجماعي التعاوني','تلزمنا بحل واحد قاطع']);
F(3,'كلمة «أن» (We) في صيغة HMW تؤكد على العمل الفردي.','كلمة (We) تؤكد على العمل الجماعي التعاوني.');
T(3,'صيغة HMW تصوغ المشكلة كتحدٍّ مفتوح للابتكار، بدلاً من صياغتها كعقبة.');
M(3,'في المثال: «كيف يمكننا أن نساعد أحمد على إدارة معلوماته في تطبيق صحتي ليتمكن من التركيز على جودة حياته دون قلق مستمر؟»، يمثل «أحمد»:',['المستخدم','الحاجة','الرؤية العميقة (Insight)','المصمم']);
T(3,'في مثال «أحمد» وتطبيق صحتي، تمثل عبارة «ليتمكن من التركيز على جودة حياته دون قلق مستمر» الرؤية العميقة (Insight).');
M(3,'أداة تحديد المشكلة في مرحلة التعريف:',['الأسباب الخمسة (5Whys)','تقنية SCAMPER','العصف الذهني','النموذج الأولي']);
M(3,'الغرض من تقنية الأسباب الخمسة (5Whys):',['الانتقال من الأعراض الظاهرية إلى الجذور الحقيقية للمشكلة','توليد 50 فكرة في 10 دقائق','بناء نموذج منخفض التكلفة','تقييم مصداقية المصادر']);
T(3,'تسهم تقنية الأسباب الخمسة في تجنب القفز إلى حلول سريعة، وغير فعالة.');
T(3,'إذا كان التعاطف هو عدستنا لنرى العالم بعيون المستخدم، فإن الأسباب الخمسة هي أداة «الحفر العميق».');
M(3,'في مثال نصب جيفرسون التذكاري، كانت المشكلة الظاهرة:',['تآكل أعمدة النصب الرخامية بسرعة غير طبيعية','كثرة الزوار','ضعف الإضاءة','تغير لون الرخام']);
M(3,'يقع نصب جيفرسون التذكاري في:',['واشنطن العاصمة','نيويورك','لندن','باريس']);
M(3,'في مايو 1990م سقطت من أعلى أحد أعمدة نصب جيفرسون قطعة رخام وزنها:',['50 رطلاً','10 أرطال','100 رطل','5 أرطال']);
M(3,'في مثال نصب جيفرسون، الإجابة عن السؤال «لماذا يُغسل النصب بهذا التكرار؟»:',['لأن روث الطيور يغطي النصب بكثافة','لأن العناكب تعيش هناك','لأن الإضاءة تجذب الحشرات','لأن الرخام قديم']);
M(3,'في مثال نصب جيفرسون، الإجابة عن السؤال «لماذا تكثر الطيور حول النصب؟»:',['لأن الطيور تتغذى على أعداد هائلة من العناكب التي تعيش هناك','لأن روث الطيور يغطي النصب','لأن الإضاءة تجذب الطيور','لأن الحراس يطعمونها']);
T(3,'في مثال نصب جيفرسون، كانت إضاءة النصب عند الغسق تخلق ضوءاً ناعماً معيناً يجذب الحشرات، ويحفزها على التزاوج.');
F(3,'في مثال نصب جيفرسون، لو توقفنا عند السؤال الأول لكان الحل المتسرع: «نمنع الطيور بالشبك».','الحل المتسرع عند السؤال الأول هو «نغير مواد التنظيف»، أما «نمنع الطيور بالشبك» فعند السؤال الثاني.');

// التوليد
T(3,'من تقنيات توليد الأفكار: العصف الذهني، والكتابة الذهنية، وأسوأ فكرة ممكنة، وتقنية SCAMPER.');
M(3,'التقنيتان اللتان تُستخدمان عادة في بداية مرحلة توليد الأفكار؛ لتحفيز التفكير الحر وتوسيع نطاق المشكلة:',['العصف الذهني، وأسوأ فكرة ممكنة','SCAMPER، والنمذجة','الأسباب الخمسة، وخرائط الحجج','الملاحظة، والانغماس']);
M(3,'القاعدة الذهبية في مرحلة توليد الأفكار:',['«لا توجد فكرة غير مقبولة»','«الجودة أهم من الكمية»','«انتقد كل فكرة فوراً»','«اختر الفكرة الأولى»']);
