T(3,'وفق قاعدة «ركز على الكمية»: الكمية تستفز الجودة لاحقاً.');
M(3,'تقنية SCAMPER اختصار لـ:',['سبع إستراتيجيات','خمس إستراتيجيات','ست إستراتيجيات','أربع إستراتيجيات']);
M(3,'يعود أصل تقنية SCAMPER إلى:',['أفكار حول العصف الذهني، وتطويره لأساليب توليد الأفكار الإبداعية','نموذج CRAAP','إطار IDEAL','تقنية الأسباب الخمسة']);
M(3,'يرمز الحرف (S) في SCAMPER إلى:',['الاستبدال (Substitute)','الدمج (Combine)','التكييف (Adapt)','الحذف (Eliminate)']);
