M(3,'السؤال «هل توجد فكرة مشابهة يمكن الاستفادة منها، أو تعديلها؟» يرتبط بإستراتيجية:',['التكييف (Adapt)','الاستبدال (Substitute)','الحذف (Eliminate)','الاستخدام بطريقة أخرى (Put to Another Use)']);
T(3,'السؤال «هل يمكن توظيف الفكرة في سياق مختلف؟» يرتبط بإستراتيجية الاستخدام بطريقة أخرى (Put to Another Use).');
F(3,'السؤال «هل يمكن زيادة الحجم، أو السرعة، أو الجودة، أو الشكل؟» يرتبط بإستراتيجية الدمج (Combine).','يرتبط بإستراتيجية التعديل أو التكبير (Modify/Magnify).');

// النمذجة والاختبار
M(3,'في مرحلة النمذجة، ينتج فريق التصميم:',['عدداً من النسخ المصغرة منخفضة التكلفة للمنتج','خطة عمل من 50 صفحة','ميزانية ضخمة','المنتج النهائي مباشرة']);
T(3,'مرحلة النمذجة مرحلة تجريبية، تُدرس فيها الحلول واحدة تلو الأخرى، ثم تُقبل أو تُحسن أو تُرفض بناءً على تجارب المستخدمين.');
T(3,'يمكن مشاركة النماذج الأولية واختبارها داخل الفريق نفسه، أو في أقسام أخرى، أو مع مجموعة صغيرة من الأشخاص خارج فريق التصميم.');
M(3,'النموذج الأولي (Prototype) هو:',['أي شيء ملموس يمكن للمستخدم التفاعل معه','خطة عمل مكتوبة','فكرة في ذهن المصمم فقط','تقرير نهائي']);
M(3,'من أشكال النموذج الأولي:',['تمثيل مسرحي (Role-play) لخدمة معينة','خطة عمل من 50 صفحة','ميزانية تفصيلية','تقرير مالي']);
M(3,'الرسم التخطيطي على الورق في مرحلة النمذجة يسمى:',['Storyboard','Role-play','POV','HMW']);
T(3,'من أسباب النمذجة: الفشل السريع، والأقل تكلفة (Fail Fast, Fail Cheap).');
T(3,'بناء الأشياء في مرحلة النمذجة يكشف لنا عيوباً لم نكن نراها في عقولنا.');
M(3,'الغاية المثلى من بناء النموذج:',['تحويل الفكرة إلى شيء ملموس','كتابة خطة عمل مفصلة','طلب ميزانية ضخمة','إنهاء المشروع']);
F(3,'إدخال المستخدم في بناء النموذج أمر ثانوي يمكن الاستغناء عنه.','إدخال المستخدم في بناء النموذج ضرورة لا بد منها لنجاح المهمة.');
F(3,'الاختبار هو المرحلة الأخيرة في التفكير التصميمي، وهو النهاية الحقيقية للعملية.','الاختبار هو المرحلة الأخيرة، لكنه ليس النهاية الحقيقية؛ فنتائجه غالباً ما تعيدنا إلى مراحل سابقة.');
M(3,'نتائج الاختبار غالباً ما تعيدنا إلى مراحل سابقة؛ لأن الاختبار:',['يكشف رؤى جديدة لم نكن نراها من قبل','ينهي المشروع','يلغي الحاجة للتعاطف','يثبت صحة الحل دائماً']);
T(3,'في مرحلة الاختبار نجرب المنتج أو الحل على المستخدمين الحقيقيين بدقة؛ لنكتشف كيف يفكرون، ويشعرون، ويتصرفون تجاهه.');
M(3,'المراحل الخمس للتفكير التصميمي هي:',['«أنماط عمل»، وليست «خطوات صارمة»','خطوات صارمة متسلسلة إجبارياً','مرحلة واحدة متكررة','خطوات لا يمكن العودة إليها']);
T(3,'يمكن أن تحدث عدة مراحل من التفكير التصميمي في وقت واحد؛ كأن يصمم فريق نموذجاً أولياً، وفريق آخر يختبر نسخة سابقة.');

// الذكاء الاصطناعي والتفكير التصميمي
M(3,'عند الجمع بين الذكاء الاصطناعي والتفكير التصميمي، يبقى ............ مسؤولية الإنسان:',['التعاطف، والحكم الأخلاقي','تحليل كميات البيانات','إنتاج الأفكار الأولية','إنشاء النماذج الرقمية']);
F(3,'الذكاء الاصطناعي بديل عن المصمم البشري.','الذكاء الاصطناعي أداة مساعدة للمصمم، وليس بديلاً عنه.');
M(3,'دور الذكاء الاصطناعي في مرحلة «تعريف المشكلة»:',['إعادة صياغة المشكلة بعدة طرق بناءً على تحليل البيانات، واقتراح زوايا لم تخطر ببالك','إنتاج مئات الأفكار الأولية خلال ثوانٍ','محاكاة سلوك آلاف المستخدمين الافتراضيين','إنشاء نماذج أولية رقمية تفاعلية']);
M(3,'دور الذكاء الاصطناعي في مرحلة «الاختبار»:',['محاكاة سلوك آلاف المستخدمين الافتراضيين لاختبار الحل قبل تنفيذه','تحليل التعليقات لاكتشاف المشاعر','إعادة صياغة المشكلة بعدة طرق','إنتاج الأفكار الأولية']);
M(3,'دور الذكاء الاصطناعي في مرحلة «النمذجة» (Prototyping):',['إنشاء نماذج أولية رقمية تفاعلية بسرعة دون الحاجة إلى مهارات برمجية عميقة','الحكم الأخلاقي على الحل','التعاطف الحقيقي مع المستخدم','تحديد الميزانية النهائية']);
T(3,'في المثال التطبيقي لمرحلة التعاطف، استخرجت أداة تحليل المشاعر من (1000) تعليق طالب أن «القلق من الاختبارات» هو السبب الحقيقي للتأخر، وليس الكسل.');
M(3,'في المثال التطبيقي لمرحلة الاختبار، أخبر الذكاء الاصطناعي أن الحل سينجح مع:',['85% من الطلاب','55% من الطلاب','39% من الطلاب','100% من الطلاب']);
M(3,'أي مما يلي ليس من الأشياء الثلاثة التي لا يستطيع الذكاء الاصطناعي فعلها:',['تحليل كميات هائلة من البيانات','التعاطف الحقيقي','الحدس الإنساني','الحكم الأخلاقي']);
T(3,'الحدس الإنساني هو تلك القفزة الإبداعية غير المنطقية التي تأتي من قلب التجربة الحية، وليس من البيانات.');
F(3,'الذكاء الاصطناعي يحلل المشاعر ويشعر بها كما يشعر الإنسان.','الذكاء الاصطناعي يحلل المشاعر، لكنه لا يشعر بها.');
M(3,'الذكاء الاصطناعي لا يعرف إن كان الحل «عادلاً» أو «مناسباً ثقافياً» لمجتمعنا؛ وهذا يتعلق بـ:',['الحكم الأخلاقي','الحدس الإنساني','التعاطف الحقيقي','تحليل البيانات']);
M(3,'البداية في الذكاء الاصطناعي «بدون» التفكير التصميمي:',['بناء التقنية أولاً','فهم الإنسان أولاً','اختبار الحل أولاً','التعاطف أولاً']);
T(3,'في الذكاء الاصطناعي «مع» التفكير التصميمي، يكون التركيز على ما يحتاجه الإنسان فعلاً.');
M(3,'النتيجة في الذكاء الاصطناعي «بدون» التفكير التصميمي:',['حل تقني معقد قد لا يستخدمه أحد','حل بسيط، وفعّال يحب الناس استخدامه','استثمار أقل، ونتائج أفضل','فهم أعمق للمستخدم']);
F(3,'الاستثمار في الذكاء الاصطناعي «مع» التفكير التصميمي: ملايين على التقنية.','مع التفكير التصميمي: استثمار أقل، ونتائج أفضل. أما «ملايين على التقنية» فهي بدون التفكير التصميمي.');
T(3,'الابتكار ليس حكراً على العباقرة، بل هو عملية منهجية تبدأ بالتعاطف.');
M(3,'يجمع التفكير التصميمي بين التعاطف والإبداع البشري، وبين قدرات الذكاء الاصطناعي:',['التحليلية، والتوليدية','العاطفية، والأخلاقية','الحدسية','الوجدانية']);

